:root :where(.wp-block-pullquote){font-size: 1.5em;line-height: 1.6;}

.xsa { display: none; }

*::-webkit-scrollbar {
    width: 3px !important;
}
*::-webkit-scrollbar-track {
    background: transparent;
}
*::-webkit-scrollbar-thumb {
    background: linear-gradient(to bottom, #00FFB7, #00F7FF);
    border-radius: 10px;
}
.corgradiente {
background: -webkit-linear-gradient(0deg,#5CFFFC,#00FFAE);
-webkit-background-clip: text;
-webkit-text-fill-color: transparent;
}
*::selection {
    color: #191C1F;
    background: #00FFB7;
}
.toolbar{
    opacity: 1 !important; 
    z-index: 99;
    position: absolute !important;
    right: 50px !important;
    top: 30px !important;
}
.prismjs-twilight .copy-to-clipboard {
    height: 400px;
}
span{
    color: #B8BBBF !important;
}

.token.punctuation{
    color: #8EC65F !important;
}

.prismjs-twilight .token.atrule {
    color: #8EC65F !important;
}
span .token{
    color: #8EC65F !important;
}


.prismjs-twilight pre[class*=language-] {
    border: 0;
}
.toolbar::after {
  background: linear-gradient(90deg, #0C0E0F, #fff, #0C0E0F);
  background-repeat: no-repeat;
  background-size: 80%;
  animation: animate 2s linear infinite;
  -webkit-background-clip: text;
  -webkit-text-fill-color: rgba(255, 255, 255, 0.5);
}
@keyframes animate {
  0% {
    background-position: -500%;
  }
  100% {
    background-position: 500%;
  }
}

.toolbar::after {
  font-family: Questrial;
  color: white;
  font-size: 18px;
  font-weight: 400;
  content: "Clique aqui para copiar";
  text-align: center;
  line-height: 1.2em;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  transform: translate(-50%,-50%);
  left: 50%;
  top:50%;
  z-index: 99;
  position: absolute;
  width: 100%;
  height: 100%;
}

.copy-to-clipboard div.code-toolbar>.toolbar a, .copy-to-clipboard div.code-toolbar>.toolbar button, .copy-to-clipboard div.code-toolbar>.toolbar span {
    color: transparent !important;
    padding: 20px 110px;
    border-radius: 20px;
    background: #0C0E0F;
    border: 2px solid #2A3338;
    filter: drop-shadow(0px 20px 15px #0C0E0F);
}
.copy-to-clipboard div.code-toolbar>.toolbar a:active,
.copy-to-clipboard div.code-toolbar>.toolbar button:active,
.copy-to-clipboard div.code-toolbar>.toolbar span:active {
    border: 2px solid #00FFAE !important;
}

.toolbar:hover{
    transform: scale(1.1);
    transition: 0.5s !important;
}
.toolbar{
    transition: 1s !important;
}


.highlight-height.line-numbers.language-css{
 background: #191C1F !important;  
 box-shadow: none;
box-shadow: inset 0px 0px 50px 5px #353C42 !important;
 border-radius: 40px;
 height: 200px;
 overflow-x: hidden !important;
 border: 2px solid #353C42;
}
.highlight-height.line-numbers.language-javascript{
 background: #191C1F !important;  
 box-shadow: none;
box-shadow: inset 0px 0px 50px 5px #353C42 !important;
 border-radius: 40px;
 height: 200px;
 overflow-x: hidden !important;
 border: 2px solid #353C42;
}
.highlight-height.line-numbers.language-html{
 background: #191C1F !important;  
 box-shadow: none;
box-shadow: inset 0px 0px 50px 5px #353C42 !important;
 border-radius: 40px;
 height: 200px;
 overflow-x: hidden !important;
 border: 2px solid #353C42;	
}

img:is([sizes="auto" i], [sizes^="auto," i]) { contain-intrinsic-size: 3000px 1500px }

img.wp-smiley, img.emoji {
		display: inline !important;
		border: none !important;
		box-shadow: none !important;
		height: 1em !important;
		width: 1em !important;
		margin: 0 0.07em !important;
		vertical-align: -0.1em !important;
		background: none !important;
		padding: 0 !important;
	}

